# SAI2 - Apply updated LearnerOnboardingTour.tsx (detailed steps)
# Run this from: D:\Rozmarrah-CUST\Saim Ashraf\Saachi AI\Working\Code\Saachi_ai_1\SAI2
# =================================================================

$ErrorActionPreference = "Stop"

$root = Get-Location
$targetPath = Join-Path $root "apps\web\components\ui\learner-onboarding-tour.tsx"

if (-not (Test-Path $targetPath)) {
    Write-Host "File not found at expected path:" -ForegroundColor Red
    Write-Host "  $targetPath" -ForegroundColor Red
    Write-Host "Aborting - no changes made." -ForegroundColor Red
    exit 1
}

# Backup the existing file first
$backupPath = "$targetPath.bak"
Copy-Item -Path $targetPath -Destination $backupPath -Force
Write-Host "Backed up existing file to:" -ForegroundColor Cyan
Write-Host "  $backupPath" -ForegroundColor White

# Base64-encoded new file content (UTF-8, no BOM) - decoded and written via
# WriteAllBytes to avoid the mojibake / encoding corruption issue.
$base64Content = ""

$bytes = [System.Convert]::FromBase64String($base64Content)
[System.IO.File]::WriteAllBytes($targetPath, $bytes)

Write-Host ""
Write-Host "Updated successfully:" -ForegroundColor Green
Write-Host "  $targetPath" -ForegroundColor White
Write-Host ""
Write-Host "Next steps:" -ForegroundColor Yellow
Write-Host "  1. Review the diff (git diff) to confirm it looks right." -ForegroundColor Yellow
Write-Host "  2. git add . ; git commit -m 'Expand learner onboarding tour with detailed steps' ; git push" -ForegroundColor Yellow
Write-Host "  3. Confirm Vercel redeploys, then hard-refresh (Ctrl+Shift+R) saachi-ai-remastered.vercel.app" -ForegroundColor Yellow
Write-Host "     (the 3-step version you're seeing now is a stale/old deployment, not your local source)" -ForegroundColor Yellow